find /home/user/Shepherd/.claudinite/shared/engine/scheduler/queue -iname "run-record.mjs" -o -iname "converge-item.mjs" | xargs -I{} echo {}
echo "---"
cat /home/user/Shepherd/.claudinite/shared/engine/scheduler/queue/run-record.mjs 2>&1 | head -80

